r.DEL_YN = 'N'
AND r.RECIPE_TITLE LIKE '%' || #{keyword} || '%' ESCAPE '\'
AND r.RECIPE_TYPE = #{recipeType}
AND r.COOKING_METHOD = #{cookingMethod}
AND r.RECIPE_NO NOT IN ( SELECT mat.RECIPE_NO FROM MATERIAL mat JOIN MEMBER_ALLERGY ma ON mat.MATERIAL_NAME LIKE '%' || ma.MATERIAL_NAME || '%' WHERE ma.MEMBER_NO = #{memberNo} )
AND r.RECIPE_NO NOT IN ( SELECT mat.RECIPE_NO FROM MATERIAL mat WHERE
mat.MATERIAL_NAME LIKE '%' || #{ex} || '%' ESCAPE '\'
